async function api(action:string,tenantId?:string,activityId?:string){const url=new URL('/api/control',window.location.origin);url.searchParams.set('action',action);if(tenantId)url.searchParams.set('tenantId',tenantId);if(activityId)url.searchParams.set('activityId',activityId);const r=await fetch(url,{cache:'no-store'});const d=await r.json() as WireResponse;if(!r.ok)throw new Error(d.error);return d;}
async function post(data:unknown){const r=await fetch('/api/control',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const d=await r.json() as WireResponse;if(!r.ok)throw new Error(d.error);return d;}
