 async function save(p:any){setBusy(p.id);setFeedback('');try{await post({action:'save_plan',id:p.id,nameAr:p.name_ar,nameEn:p.name_en,monthlyPrice:p.monthly_price,yearlyPrice:p.yearly_price||0,currency:p.currency,enabled:Boolean(Number(p.enabled)),descriptionAr:p.description_ar||'',descriptionEn:p.description_en||'',descriptionFr:p.description_fr||''});setFeedback(locale==='ar'?'تم حفظ بيانات الباقة بنجاح':'Plan details saved')}catch{setFeedback(locale==='ar'?'تعذر حفظ الباقة؛ لم تتغير البيانات':'Could not save plan; no changes were applied')}finally{setBusy('')}}
